## Patch Sketch

```js
const crypto = require('crypto');

const TOLERANCE_S = 5 * 60; // 5 minutes

function verify(header, body, secret) {
  // 1. Parse header
  if (typeof header !== 'string') return false;
  const parts = Object.fromEntries(
    header.split(',').map(p => p.split('=').map(s => s.trim()))
  );
  const { t, v1 } = parts;

  // 2. Validate timestamp — reject missing, non-integer, or stale
  const ts = parseInt(t, 10);
  if (!Number.isFinite(ts) || String(ts) !== t) return false;
  const age = Math.floor(Date.now() / 1000) - ts;
  if (age < 0 || age > TOLERANCE_S) return false;

  // 3. Recompute HMAC over "t.<body>" (binds timestamp to signature)
  const signedPayload = `${t}.${body}`;
  const expected = crypto
    .createHmac('sha256', secret)
    .update(signedPayload)
    .digest('hex');

  // 4. Reject malformed hex before buffer allocation
  if (typeof v1 !== 'string' || !/^[0-9a-f]{64}$/i.test(v1)) return false;

  // 5. Constant-time comparison
  const a = Buffer.from(v1.toLowerCase(), 'hex');
  const b = Buffer.from(expected, 'hex');
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}
```

**What changed and why:**
- Header parsed for `t` and `v1`; missing either field → false immediately.
- `parseInt` result is round-tripped back to string to reject floats/junk ("1.5", "123abc").
- Signed payload includes the timestamp (`t.<body>`), so a valid signature cannot be reused against a different timestamp window.
- Regex enforces exactly 64 lowercase hex chars before `Buffer.from`, preventing `Buffer` allocation on attacker-controlled garbage and avoiding the length-mismatch panic that would crash `timingSafeEqual`.
- `crypto.timingSafeEqual` replaces `===`, eliminating the early-exit timing side-channel.

